use std::fmt::Write as _;

use crate::catalog::Catalog;
use crate::identifier::{camel, pascal};

pub(crate) fn render(source: &[Catalog]) -> String {
    let mut out = String::from(
        "// Generated by jayjay-i18n from its en-US catalog. Do not edit.\n\npublic enum Localized {\n",
    );
    for catalog in source {
        writeln!(out, "    public enum {} {{", pascal(&catalog.stem)).unwrap();
        for message in &catalog.messages {
            let name = camel(&message.name);
            let mut params = Vec::new();
            let mut values = Vec::new();
            for arg in &message.args {
                let label = camel(&arg.name);
                let (kind, value) = if arg.number {
                    ("Int", format!(".number(value: Int64({label}))"))
                } else {
                    ("String", format!(".text(value: {label})"))
                };
                params.push(format!("{label}: {kind}"));
                values.push(format!("{:?}: {value}", arg.name));
            }
            let call = format!(
                "localizedMessage(id: {:?}, args: [{}])",
                message.id,
                if values.is_empty() {
                    ":".to_owned()
                } else {
                    values.join(", ")
                }
            );
            if params.is_empty() {
                writeln!(out, "        public static var {name}: String {{ {call} }}").unwrap();
            } else {
                writeln!(
                    out,
                    "        public static func {name}({}) -> String {{\n            {call}\n        }}",
                    params.join(", ")
                )
                .unwrap();
            }
        }
        out.push_str("    }\n");
    }
    out.push_str("}\n");
    out
}
